use std::{env,fs,io::{self,Write}};use spore_core::{creature_generated_skin_kernel_v1::Lane,creature_skin_grid_geometry_v1::{derive_and_pack,ArithmeticAdmission},native_sse::Policy};
fn main(){let a:Vec<_>=env::args().collect();assert_eq!(a.len(),2);let b=fs::read(&a[1]).unwrap();assert_eq!(b.len(),372);let u:Vec<u32>=b.chunks_exact(4).map(|v|u32::from_le_bytes(v.try_into().unwrap())).collect();let n=u[8] as usize;assert!(n<=12);let f=|i|f32::from_bits(u[i]);let lo=[f(0),f(1),f(2)];let hi=[f(3),f(4),f(5)];let lanes:Vec<_>=(0..n).map(|i|{let x=9+i*7;Lane{center:[f(x),f(x+1),f(x+2)],cutoff:f(x+3),scale:f(x+4),coefficient:f(x+5),key:u[x+6]}}).collect();let (g,p)=derive_and_pack(&lanes,lo,hi,f(6),f(7),Policy::Mxcsr1f80,ArithmeticAdmission).unwrap();let cells=p.cells();let mut result=Vec::new();for v in g.origin.into_iter().chain(g.scale){result.extend_from_slice(&v.to_bits().to_le_bytes());}for cell in cells {let ks:Vec<_>=cell.unwrap_or(&[]).iter().flat_map(|r|r.iter()).filter(|v|v.cutoff>0.).map(|v|v.key).collect();assert!(ks.len()<=12);result.extend_from_slice(&(ks.len() as u32).to_le_bytes());for i in 0..12{result.extend_from_slice(&ks.get(i).copied().unwrap_or(0).to_le_bytes());}}io::stdout().write_all(&result).unwrap();}
